pub fn arguments<T: DeserializeOwned>(&self) -> Result<T, serde_json::Error> {
        serde_json::from_value(self.arguments.clone())
    }

fix:
pub fn arguments<T: DeserializeOwned>(&self) -> Result<T, serde_json::Error> {
        T::deserialize(&self.arguments)
    }
// serde_json implements Deserializer for &Value, so the whole JSON tree is no longer cloned just to decode it. Deserialize is already imported.

