pub fn is_observing(&self, route: RouteId) -> bool {
        !self.inner.subscribers_of(route).is_empty()
    }

fix:
pub fn is_observing(&self, route: RouteId) -> bool {
        self.inner.subscribers.borrow().get(&route).is_some_and(|list| list.iter().any(|aware| aware.strong_count() != 0))
    }
